def disconnect(self, sid=None):
        """Disconnect a client.

        :param sid: The session id of the client to close. If this parameter
                    is not given, then all clients are closed.
        """
        if sid is None:
            self.clients = {}
        else:
            self.clients.pop(sid, None)

